import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    // max-heap of costs backed by a growable array
    static final class Heap {
        long[] a = new long[1];
        int size;

        void push(long v) {
            if (size == a.length) a = java.util.Arrays.copyOf(a, size * 2);
            int i = size++;
            a[i] = v;
            while (i > 0) {
                int p = (i - 1) / 2;
                if (a[p] >= a[i]) break;
                long t = a[p]; a[p] = a[i]; a[i] = t;
                i = p;
            }
        }

        long pop() {
            long top = a[0];
            a[0] = a[--size];
            int i = 0;
            while (true) {
                int l = 2 * i + 1, r = l + 1, big = i;
                if (l < size && a[l] > a[big]) big = l;
                if (r < size && a[r] > a[big]) big = r;
                if (big == i) break;
                long t = a[big]; a[big] = a[i]; a[i] = t;
                i = big;
            }
            return top;
        }
    }

    public static void main(String[] args) throws IOException {
        StringBuilder out = new StringBuilder();
        for (int t = nextInt(); t > 0; t--) {
            int n = nextInt();
            long budget = nextLong();
            int[] parent = new int[n + 1];
            long[] leader = new long[n + 1], sum = new long[n + 1];
            Heap[] heaps = new Heap[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = nextInt();
                long c = nextLong();
                leader[i] = nextLong();
                heaps[i] = new Heap();
                heaps[i].push(c);
                sum[i] = c;
            }
            long best = 0;
            // R[i] < i, so children are finished before their parent
            for (int v = n; v >= 1; v--) {
                Heap h = heaps[v];
                while (sum[v] > budget) sum[v] -= h.pop();
                best = Math.max(best, leader[v] * h.size);
                int p = parent[v];
                if (p > 0) {
                    // merge the smaller heap into the larger one
                    if (heaps[p].size < h.size) {
                        heaps[v] = heaps[p];
                        heaps[p] = h;
                        long s = sum[p]; sum[p] = sum[v]; sum[v] = s;
                    }
                    Heap small = heaps[v], large = heaps[p];
                    for (int i = 0; i < small.size; i++) {
                        large.push(small.a[i]);
                        sum[p] += small.a[i];
                    }
                    heaps[v] = null;
                }
            }
            out.append(best).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

// max-heap of costs
type heap struct{ a []int64 }

func (h *heap) push(v int64) {
	h.a = append(h.a, v)
	i := len(h.a) - 1
	for i > 0 {
		p := (i - 1) / 2
		if h.a[p] >= h.a[i] {
			break
		}
		h.a[p], h.a[i] = h.a[i], h.a[p]
		i = p
	}
}

func (h *heap) pop() int64 {
	top := h.a[0]
	last := len(h.a) - 1
	h.a[0] = h.a[last]
	h.a = h.a[:last]
	i := 0
	for {
		l, r, big := 2*i+1, 2*i+2, i
		if l < last && h.a[l] > h.a[big] {
			big = l
		}
		if r < last && h.a[r] > h.a[big] {
			big = r
		}
		if big == i {
			break
		}
		h.a[big], h.a[i] = h.a[i], h.a[big]
		i = big
	}
	return top
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for t := nextInt(); t > 0; t-- {
		n, budget := int(nextInt()), nextInt()
		parent := make([]int, n+1)
		leader := make([]int64, n+1)
		heaps := make([]*heap, n+1)
		sum := make([]int64, n+1)
		for i := 1; i <= n; i++ {
			parent[i] = int(nextInt())
			c := nextInt()
			leader[i] = nextInt()
			heaps[i] = &heap{a: []int64{c}}
			sum[i] = c
		}
		var best int64
		// R[i] < i, so children are finished before their parent
		for v := n; v >= 1; v-- {
			h := heaps[v]
			for sum[v] > budget {
				sum[v] -= h.pop()
			}
			best = max(best, leader[v]*int64(len(h.a)))
			if p := parent[v]; p > 0 {
				// merge the smaller heap into the larger one
				if len(heaps[p].a) < len(h.a) {
					heaps[p], heaps[v] = heaps[v], heaps[p]
					sum[p], sum[v] = sum[v], sum[p]
				}
				for _, c := range heaps[v].a {
					heaps[p].push(c)
					sum[p] += c
				}
				heaps[v] = nil
			}
		}
		w.WriteString(strconv.FormatInt(best, 10))
		w.WriteByte('\n')
	}
}
